fn fetch_registry_config(context: &CliContext, args: RegistryConfigArgs) -> Result<(), CliError> {
	let address = match &args.address {
		Some(value) => CliContext::pubkey("--address", value)?,
		None => {
			let admin = match &args.admin {
				Some(value) => CliContext::pubkey("--admin", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "registry-config".to_string(),
						seed: "--admin".to_string(),
					});
				}
			};
			let seeds: &[&[u8]] = &["registry".as_bytes(), admin.as_ref()];
			Pubkey::find_program_address(seeds, &context.program_address).0
		}
	};
	let data = context.fetch_account(&address)?;
	let value = match role_registry_program_client::accounts::RegistryConfig::from_bytes(&data) {
		Ok(account) => registry_config_json(&account),
		Err(error) => {
			return Err(CliError::AccountDecode {
				address: address.to_string(),
				message: error.to_string(),
			});
		}
	};
	print_value(context.json, "registry-config", &address, &value);
	Ok(())
}

fn fetch_role_entry(context: &CliContext, args: RoleEntryArgs) -> Result<(), CliError> {
	let address = match &args.address {
		Some(value) => CliContext::pubkey("--address", value)?,
		None => {
			let registry = match &args.registry {
				Some(value) => CliContext::pubkey("--registry", value)?,
				None => {
					return Err(CliError::MissingSeed {
						account: "role-entry".to_string(),
						seed: "--registry".to_string(),
					});
				}
			};
			let role_id = args.role_id.ok_or_else(|| {
				CliError::MissingSeed {
					account: "role-entry".to_string(),
					seed: "--role_id".to_string(),
				}
			})?;
			let role_id_bytes = role_id.to_le_bytes();
			let seeds: &[&[u8]] = &[
				"role-entry".as_bytes(),
				registry.as_ref(),
				role_id_bytes.as_ref(),
			];
			Pubkey::find_program_address(seeds, &context.program_address).0
		}
	};
	let data = context.fetch_account(&address)?;
	let value = match role_registry_program_client::accounts::RoleEntry::from_bytes(&data) {
		Ok(account) => role_entry_json(&account),
		Err(error) => {
			return Err(CliError::AccountDecode {
				address: address.to_string(),
				message: error.to_string(),
			});
		}
	};
	print_value(context.json, "role-entry", &address, &value);
	Ok(())
}

fn registry_config_json(
	account: &role_registry_program_client::accounts::RegistryConfigZc,
) -> Value {
	json!({
		"admin": account.admin.to_string(),
		"role_count": account.role_count.get(),
		"bump": account.bump,
	})
}

fn role_entry_json(account: &role_registry_program_client::accounts::RoleEntryZc) -> Value {
	json!({
		"registry": account.registry.to_string(),
		"role_id": account.role_id.get(),
		"grantee": account.grantee.to_string(),
		"permissions": account.permissions.get(),
		"active": account.active.get(),
		"bump": account.bump,
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
